import * as z from 'zod/v4';
import { Tinybird } from '@chronark/zod-bird';

if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Dub's client (apps/web/lib/tinybird/client.ts)
export const tb = new Tinybird({ token: process.env.TINYBIRD_API_KEY, baseUrl: process.env.TINYBIRD_API_URL });

// Dub's dub_links_metadata event (apps/web/lib/tinybird/record-link.ts)
export const dubLinksMetadataSchema = z.object({
  link_id: z.string(),
  domain: z.string(),
  key: z.string(),
  url: z.string().default(''),
  tag_ids: z.array(z.string()).default([]),
  folder_id: z.string().nullish().transform((v) => (v ? v : '')),
  tenant_id: z.string().nullable().transform((v) => (v ? v : '')),
  program_id: z.string().nullable().transform((v) => (v ? v : '')),
  partner_id: z.string().nullish().transform((v) => (v ? v : '')),
  partner_group_id: z.string().nullish().transform((v) => (v ? v : '')),
  partner_tag_ids: z.array(z.string()).default([]),
  workspace_id: z.string().nullish().transform((v) => (v ? v : '')),
  created_at: z.date().transform((v) => v.toISOString().replace('T', ' ').replace('Z', '')),
  deleted: z.boolean().default(false).transform((v) => (v ? 1 : 0)),
});

export const WORKSPACE = 'cm5hkq1lp0001vj08n3c7tq2a';
// The entry's own endpoint (a synthetic choice: Dub's endpoints read the whole of its datafiles): a Workspace's live
// links from dub_links_metadata, published as tb push publishes an endpoint node
export const linksOf = tb.buildPipe({
  pipe: 'links_of_workspace',
  parameters: z.object({ workspaceId: z.string() }),
  data: z.object({ link_id: z.string(), domain: z.string(), key: z.string(), url: z.string() }),
});

