import assert from 'node:assert/strict';
import { dubLinksMetadataSchema, linksOf, tb, WORKSPACE } from './tinybird.mjs';

const api = process.env.TINYBIRD_API_URL;
const auth = { authorization: `Bearer ${process.env.TINYBIRD_API_KEY}` };
const answer = async (response, what) => { const body = await response.json(); assert.equal(response.status, 200, `${what}: ${JSON.stringify(body)}`); return body; };
// `tb push`, as Dub deploys its datafiles: the dub_links_metadata Data Source from its .datasource file
await answer(await fetch(`${api}/v0/datasources`, { method: 'POST', headers: { ...auth, 'content-type': 'application/x-www-form-urlencoded' }, body: "name=dub_links_metadata&description=&schema=%60timestamp%60+DateTime+%60json%3A%24.timestamp%60+DEFAULT+now%28%29%2C%60link_id%60+String+%60json%3A%24.link_id%60%2C%60domain%60+String+%60json%3A%24.domain%60%2C%60key%60+String+%60json%3A%24.key%60%2C%60url%60+String+%60json%3A%24.url%60%2C%60tag_ids%60+Array%28String%29+%60json%3A%24.tag_ids%5B%3A%5D%60%2C%60workspace_id%60+String+%60json%3A%24.workspace_id%60%2C%60created_at%60+DateTime64%283%29+%60json%3A%24.created_at%60%2C%60deleted%60+UInt8+%60json%3A%24.deleted%60%2C%60program_id%60+String+%60json%3A%24.program_id%60%2C%60tenant_id%60+String+%60json%3A%24.tenant_id%60%2C%60partner_id%60+String+%60json%3A%24.partner_id%60%2C%60folder_id%60+String+%60json%3A%24.folder_id%60%2C%60partner_group_id%60+String+%60json%3A%24.partner_group_id%60&format=ndjson&engine=MergeTree&engine_partition_key=toYear%28timestamp%29&engine_sorting_key=timestamp%2C+link_id%2C+workspace_id&branch_mode=None" }), 'the Data Source');
const pipe = await answer(await fetch(`${api}/v0/pipes`, { method: 'POST', headers: { ...auth, 'content-type': 'application/json' }, body: JSON.stringify({
  name: 'links_of_workspace', description: "A Workspace's live links",
  nodes: [{ name: 'endpoint', type: 'standard', sql: "%\nSELECT link_id, domain, key, url\nFROM dub_links_metadata\nWHERE workspace_id = {{ String(workspaceId, required=True) }} AND deleted == 0\nORDER BY created_at" }],
}) }), 'the Pipe');
await answer(await fetch(`${api}/v0/pipes/links_of_workspace/nodes/${pipe.nodes[0].id}/endpoint`, { method: 'POST', headers: auth }), 'the endpoint');

// a link made: Dub's recordLink (buildIngestEndpoint, wait: true)
const recordLinkTB = tb.buildIngestEndpoint({ datasource: 'dub_links_metadata', event: dubLinksMetadataSchema, wait: true });
const ingested = await recordLinkTB({
  link_id: 'link_08N3C7TQ2A', domain: 'lnk.loopline.fm', key: 'nightshift', url: 'https://nightshift.example.fm/episodes',
  tag_ids: [], folder_id: null, tenant_id: null, program_id: null, partner_id: null, partner_group_id: null, partner_tag_ids: [],
  workspace_id: WORKSPACE, created_at: new Date('2026-01-07T10:00:00.000Z'), deleted: false,
});
assert.deepEqual(ingested, { successful_rows: 1, quarantined_rows: 0 });
const read = await linksOf({ workspaceId: WORKSPACE });
assert.deepEqual(read.data, [{ link_id: 'link_08N3C7TQ2A', domain: 'lnk.loopline.fm', key: 'nightshift', url: 'https://nightshift.example.fm/episodes' }]);
console.log(JSON.stringify({ ingested, links: read.data }));

