import assert from 'node:assert/strict';
import { linksOf, WORKSPACE } from './tinybird.mjs';

// the dashboard's read after a restart: the link Dub recorded, from the published endpoint, nothing ingested again
const read = await linksOf({ workspaceId: WORKSPACE });
assert.deepEqual(read.data, [{ link_id: 'link_08N3C7TQ2A', domain: 'lnk.loopline.fm', key: 'nightshift', url: 'https://nightshift.example.fm/episodes' }]);
assert.deepEqual(read.meta.map((column) => column.name), ['link_id', 'domain', 'key', 'url']);
console.log(JSON.stringify({ retained: read.data }));
